// The callees of mainLoop's title menu and session dispatch that no other module ports (phase 3.8, stream 38j; module
// `menu`, port/src/sim/menu.cpp, tests port/test/test_menu.py; notes log/p38/38j_notes.md). The menu and session bodies
// themselves are mainLoop's code and live in the tick module (port/src/sim/tick_menu.inc, generated by
// log/p38/38j/conv_menu.py from shim/src/re/c3fy.cpp parts MV and SV); this module also registers their negative-control
// switch as the pseudo-function `tick.menu`.
#ifndef PORTSIM_SIM_MENU_H
#define PORTSIM_SIM_MENU_H

#include <cstdint>

#include "portsim/registry.h"

namespace portsim {

// loadWorldAssets (re/analysis/render/0043dbe0, C3 hook source shim/src/re/c3fv.cpp): the world's art for the course type
// g_courseType, simulation part. The art itself (palettes, sprite sheets, flics, cut rectangles) is the renderer's; what
// stays: for a course type 0..3 the object-type table g_tileTypeAttrs is copied from its initial image and the type's names
// and attribute bytes are written into it and into the build-item names; the flic-load counter g_flicLoadCount advances by
// the number of flics the type's manifest loads (loadFlic: every 100th load shows the loading screen, which draws two
// numbers of the game's generator, but only while g_difficulty is -1). Returns 0.
int32_t load_world_assets(Ctx &ctx);

// loadInterfaceArt(full) (re/analysis/render/00442180, c3fv.cpp), the new-game part (full == 0): the course's tables cleared,
// the ranking rows drawn from the game's generator, then loadWorldAssets. full != 0 (the boot art of mainLoop's Setup):
// MissingResource. Returns 0.
int32_t load_interface_art(Ctx &ctx, int32_t full);

// startNewCourse (re/analysis/boot/0046ddd0, c3ev.cpp): the championship's set-up: the course list
// (loadGameBrowserScreen(1, 1)); 0 there returns 0. Otherwise g_difficulty is put back, cash 1000, g_date 0x2c00, g_flags
// = the championship flag (1 << 26), then the pro list (pickAProScreen): 0 there clears g_flags and returns 0; else
// loadGolfPro and cash 1000 again, returns 1.
int32_t start_new_course(Ctx &ctx);

// pickAProScreen (re/analysis/frontend/0043a8c0, c3fw.cpp): the modal list of the theme's pro golfers, simulation effects
// only. The theme name is set to the standard theme's for the screen; the list is listMatchingFiles over the .pro pattern;
// a press on a row loads that pro's file (loadThemeFile(name, 0, 1)) and selects it (its card then builds its texts: the
// golfer comment of kind 0x3e, the ten skill rows); the load button loads the selection again and returns 1, back returns
// 0 with the theme name left as the screen set it, an empty selection returns 0; both other exits restore the theme name.
int32_t pick_a_pro_screen(Ctx &ctx);

}  // namespace portsim

#endif  // PORTSIM_SIM_MENU_H
